async function insertionEditor(filename, preserveFocus = false) {
  let editor = vscode.window.visibleTextEditors.find((item) => path.resolve(item.document.fileName).toLowerCase() === path.resolve(filename || '').toLowerCase());
  if (!editor && filename) editor = await vscode.window.showTextDocument(await vscode.workspace.openTextDocument(vscode.Uri.file(filename)), { preview: false, preserveFocus });
  return editor;
}
function insertionIssue(text, filename, line) {
  if (languageFor(filename) !== 'zss') return '';
  return zssInsertionContext(text, line).issue;
}
async function reportInsertionContext(owner, filename, services = {}) {
  const isCurrent = services.isCurrent || (() => sessions.get(sessionKey(owner.defPath)) === owner);
  const reject = async (label, issue) => {
    if (owner) { owner.capture = null; owner.generatedSnapshot = null; }
    const context = { valid: false, label, issue };
    if (owner && !owner.disposed && isCurrent()) await owner.panel.webview.postMessage({ type: 'insertionContext', context });
    return { editor: null, context };
  };
  if (!owner || fileKey(filename) !== fileKey(owner.selectedSource) || !projectNavigation(owner.navigation).visibleItems.some(item => fileKey(item.filename) === fileKey(filename))) {
    if (owner) await invalidateSpatialCapture(owner, 'Choose one of this composer session’s assigned state files.');
    return reject('Unassigned source', 'Choose one of this composer session’s assigned state files.');
  }
  const editor = await insertionEditor(filename, true);
  if (!editor) return reject('No source editor', 'Open the insertion source and place its cursor first.');
  const observed = { uri: editor.document.uri.toString(), version: String(editor.document.version ?? hash(editor.document.getText())), sha256: hash(editor.document.getText()), cursor: { line: editor.selection.active.line, character: editor.selection.active.character }, generation: owner.generation };
  const initialContext = languageFor(filename) === 'zss' ? zssInsertionContext(editor.document.getText(), editor.selection.active.line) : { valid: true, label: `CNS source at line ${editor.selection.active.line + 1}`, issue: '' };
  const expectedEpoch = (owner.authorityEpoch || 0) + 1;
  await invalidateSpatialCapture(owner, initialContext.valid ? 'Refreshing checked insertion authority.' : initialContext.issue);
  if (owner.disposed || !isCurrent() || owner.authorityEpoch !== expectedEpoch || owner.generation !== observed.generation) return reject('Stale context', 'The composer or generated plan changed while the insertion context was checked. Recheck context.');
  const freshEditor = (vscode.window.visibleTextEditors || []).find(item => item.document.uri.toString() === observed.uri && fileKey(item.document.fileName) === fileKey(filename));
  const stillAssigned = fileKey(filename) === fileKey(owner.selectedSource) && projectNavigation(owner.navigation).visibleItems.some(item => fileKey(item.filename) === fileKey(filename)) && sourceFiles(owner.defPath).some(item => fileKey(item) === fileKey(filename));
  const unchanged = freshEditor && !freshEditor.document.isClosed && String(freshEditor.document.version ?? hash(freshEditor.document.getText())) === observed.version && hash(freshEditor.document.getText()) === observed.sha256 && freshEditor.selection.active.line === observed.cursor.line && freshEditor.selection.active.character === observed.cursor.character;
  if (!stillAssigned || !unchanged) return reject('Stale context', 'The source, document, or cursor changed while the insertion context was checked. Recheck context.');
  const context = languageFor(filename) === 'zss' ? zssInsertionContext(freshEditor.document.getText(), freshEditor.selection.active.line) : { valid: true, label: `CNS source at line ${freshEditor.selection.active.line + 1}`, issue: '' };
  if (!context.valid) return reject(context.label, context.issue);
  registerSpatialContext(owner); owner.capture = captureSource(owner, freshEditor, contextSnapshot(owner)); claimSpatial(owner); owner.capture = captureSource(owner, freshEditor, contextSnapshot(owner)); owner.generatedSnapshot = owner.capture ? makeGeneratedSnapshot(owner) : null;
  if (!owner.capture || !owner.generatedSnapshot || owner.disposed || !isCurrent() || owner.authorityEpoch !== expectedEpoch) return reject('Stale context', 'Insertion authority could not be established safely. Recheck context.');
  await owner.panel.webview.postMessage({ type: 'insertionContext', context });
  if (owner.disposed || !isCurrent() || owner.authorityEpoch !== expectedEpoch || !currentCapture(owner)) return reject('Stale context', 'The insertion context changed before authority could be published. Recheck context.');
  await owner.panel.webview.postMessage({ type: 'spatialToolbarState', model: spatialToolbarModel(owner) });
  if (owner.disposed || !isCurrent() || owner.authorityEpoch !== expectedEpoch || !currentCapture(owner)) return reject('Stale context', 'The insertion context changed before authority could be published. Recheck context.');
  await owner.panel.webview.postMessage({ type: 'generatedAuthority', snapshot: projectGeneratedCodeSnapshot(owner.generatedSnapshot), targetId: `cursor:${owner.capture.opaqueTarget}` });
  return { editor: freshEditor, context };
}
function generatedInsertion(mode, plan) {
  return mode === 'position' ? spatial.generatePosition(plan) : spatial.generateExplod(plan);
}
async function insertReviewedGeneration(owner, message, services = {}) {
  const generated = generatedInsertion(owner.mode, owner.plan), capture = currentCapture(owner), snapshot = owner.generatedSnapshot;
  const warn = services.warn || ((text) => vscode.window.showWarningMessage(text));
  if (!generated.valid) { await warn('Fix the reported generator errors before inserting controller code.'); return false; }
  if (!capture || !snapshot || message.source !== capture.filename || typeof message.code !== 'string' || message.code !== generated.code || generated.code !== snapshot.artifacts[0]?.text) {
    await warn('The plan changed after the displayed code was generated. Review the refreshed controller code, then choose Insert again.');
    return false;
  }
  return insertAuthorizedGeneration(owner, { type: INVOKE_TYPE, surfaceId: 'code.spatial', snapshotDigest: snapshot.snapshotDigest, operationId: 'insert-cursor', artifactIds: ['spatial-controller'], targetIds: [`cursor:${capture.opaqueTarget}`] }, services);
}
